      "most_likely_effort": 8
    },
    {
      "activity_id": "A16",
      "activity_name": "U6 design: module trace property with wildcards",
      "property_note": "",
      "activity_description": "Design 'module.<label>.trace' / 'module.*.trace' property parsing and wiretap-based tracing (global channel interceptor with pattern matching) to logging/notification channels.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A17",
      "activity_name": "U6 implementation: wiretap tracing per deployment properties",
      "activity_description": "Implement deployment-property parsing, wildcard selector matching, WireTap insertion on matched modules' channels, and binding of the trace output channel.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A18",
      "activity_name": "U6 testing: trace property behavior",
      "activity_description": "Tests for exact-label and wildcard tracing, interceptor ordering, and verification that traced messages reach the logging/notification sink.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A19",
      "activity_name": "U7 design: arbitrary side channels",
